import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/** The figures of a sheet's descendants. The signed-in user's name travels in the {@code X-User} header. */
@RestController
@Validated
public class ConsolidatedController {

    private final RollupService rollups;

    public ConsolidatedController(RollupService rollups) {
        this.rollups = rollups;
    }

    /**
     * The people, due-total and overdue-total of the sheet's descendants added up, the sheet itself left out; in an
     * as-of view, each descendant as it stood at the end of that date.
     */
    @GetMapping("/api/sheets/{sheetId}/descendants/figures")
    public RollupService.Consolidated descendants(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return rollups.descendantFigures(sheetId.trim());
    }

    /**
     * The people of the sheet and its descendants, each counted once over the tree, and the due-total and
     * overdue-total trimmed once over every person of the tree; in an as-of view, every sheet of the tree as it stood
     * at the end of that date.
     */
    @GetMapping("/api/sheets/{sheetId}/consolidated/figures")
    public RollupService.Consolidated consolidated(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return rollups.consolidatedFigures(sheetId.trim());
    }

    /**
     * The people on the sheet and the other sheets of its tree whose name or an alias contains the text (case ignored),
     * one line each: {@code <sheet id> <name> <due-total>}. It changes nothing.
     */
    @GetMapping("/api/sheets/{sheetId}/tree/search")
    public List<String> search(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestParam(defaultValue = "") @Size(max = 100) String name,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return rollups.search(sheetId.trim(), name);
    }

    /**
     * The people of the sheet and the other sheets of its tree, one row each: {@code [<sheet id>, <name>, <grade>,
     * <due-total>]}, this sheet's first in list order, then the other sheets' by sheet id. It changes nothing.
     */
    @GetMapping("/api/sheets/{sheetId}/tree/people")
    public List<List<String>> treePeople(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return rollups.treePeople(sheetId.trim());
    }

    /**
     * This sheet compared with another, one line per grade: {@code <grade> <this sheet's due-total> <the other's>};
     * no lines when the other sheet does not exist. It changes nothing.
     */
    @GetMapping("/api/sheets/{sheetId}/compare")
    public List<String> compare(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestParam(defaultValue = "") @Size(max = 100) String other,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return rollups.compare(sheetId.trim(), other.trim());
    }
}
